import React, { useState, useEffect } from 'react';
import { digitalTwinApi, machineApi } from '../api/client';
import {
  Cpu,
  Activity,
  Zap,
  Gauge,
  Thermometer,
  Sparkles,
  AlertTriangle,
  Play,
  Pause,
  RotateCcw,
  Wrench,
  Search,
  CheckCircle2,
  Clock,
  Radio,
  ArrowRightLeft,
  Server,
  Building,
  MapPin,
  FileText,
  Filter,
  X,
  AlertOctagon,
  Calendar,
  UserCheck,
  TrendingUp,
  ShieldAlert,
  DollarSign,
} from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line } from 'react-chartjs-2';
import { useNavigate } from 'react-router-dom';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const DigitalTwinPage = () => {
  const navigate = useNavigate();

  // Cascading Selection State
  const [selectedPlant, setSelectedPlant] = useState('Coimbatore Hub (Primary Mill)');
  const [selectedMachineType, setSelectedMachineType] = useState('Air Jet Loom');
  const [selectedMachineId, setSelectedMachineId] = useState('LOOM-201');

  // Digital Twin Data Payload
  const [twinData, setTwinData] = useState(null);
  const [loading, setLoading] = useState(false);

  // Selected Component Inspection Drawer State
  const [inspectComponent, setInspectComponent] = useState(null);

  // Available Plants & Machine Types
  const plants = [
    'Coimbatore Hub (Primary Mill)',
    'Tirupur Facility',
    'Gujarat Hub',
    'Kanchipuram Hub',
    'Salem Hub',
    'Surat Hub',
  ];

  const machineTypes = [
    'Air Jet Loom',
    'Water Jet Loom',
    'Rapier Loom',
    'Projectile Loom',
    'Shuttle Loom',
    'Circular Knitting Machine',
  ];

  const availableMachines = [
    { id: 'LOOM-201', name: 'Dornier Air Jet HD-2025', type: 'Air Jet Loom', plant: 'Coimbatore Hub (Primary Mill)' },
    { id: 'LOOM-101', name: 'Toyota JAT810 Air Jet', type: 'Air Jet Loom', plant: 'Coimbatore Hub (Primary Mill)' },
    { id: 'LOOM-104', name: 'Tsudakoma Water Jet ZAX', type: 'Water Jet Loom', plant: 'Tirupur Facility' },
    { id: 'LOOM-301', name: 'Picanol OptiMax Rapier', type: 'Rapier Loom', plant: 'Gujarat Hub' },
    { id: 'LOOM-501', name: 'Sulzer Projectile P7300', type: 'Projectile Loom', plant: 'Kanchipuram Hub' },
    { id: 'LOOM-601', name: 'Mayer & Cie Knitting', type: 'Circular Knitting Machine', plant: 'Surat Hub' },
  ];

  useEffect(() => {
    fetchTwinData(selectedMachineId);
  }, []);

  const handleLoadDigitalTwin = () => {
    fetchTwinData(selectedMachineId);
  };

  const fetchTwinData = async (mId) => {
    try {
      setLoading(true);
      const res = await digitalTwinApi.getByMachineId(mId);
      if (res && res.data && res.data.success) {
        setTwinData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch twin data:', err);
    } finally {
      setLoading(false);
    }
  };

  // Fallback Twin Data
  const twin = twinData || {
    machineId: selectedMachineId,
    assetName: `${selectedMachineType} (${selectedMachineId})`,
    manufacturer: selectedMachineType.includes('Air') ? 'Dornier' : selectedMachineType.includes('Water') ? 'Tsudakoma' : 'Picanol',
    model: 'HD-2025',
    installedYear: 2024,
    location: selectedPlant,
    department: 'High-Speed Weaving & AI Control',
    status: 'Running',
    twinStatus: {
      syncPct: 99.8,
      lastSync: '1 sec ago',
      latencyMs: 32,
      mqttState: 'Connected',
      twinState: 'Healthy',
    },
    mqttDetails: {
      topic: `textwin/telemetry/${selectedMachineId}`,
      lastMessage: '10:35:22',
      qos: 1,
      packets: 2543,
      latencyMs: 24,
    },
    energy: {
      powerKw: 6.5,
      todayEnergyKwh: 126,
      efficiencyPct: 96,
      powerFactor: 0.95,
      co2SavedKg: 14.2,
    },
    components: [
      { name: 'Motor', temp: '76.4°C', rpm: 1200, vibration: '0.28 mm/s', health: '82%', nextMaint: '5 Days', color: '#EF4444' },
      { name: 'Bearing', temp: '54.2°C', rpm: 1050, vibration: '0.18 mm/s', health: '96%', nextMaint: '25 Days', color: '#22C55E' },
      { name: 'Main Shaft', temp: '48.0°C', rpm: 1050, vibration: '0.12 mm/s', health: '92%', nextMaint: '18 Days', color: '#22C55E' },
      { name: 'Warp Beam', temp: '38.5°C', rpm: 980, vibration: '0.08 mm/s', health: '98%', nextMaint: '40 Days', color: '#22C55E' },
      { name: 'Weft Sensor', temp: '41.2°C', rpm: 1050, vibration: '0.22 mm/s', health: '62%', nextMaint: '2 Days', color: '#EF4444' },
      { name: 'Air Nozzle', temp: '44.8°C', rpm: 1050, vibration: '0.15 mm/s', health: '85%', nextMaint: '12 Days', color: '#F59E0B' },
      { name: 'Compressor', temp: '58.0°C', rpm: 1100, vibration: '0.20 mm/s', health: '88%', nextMaint: '15 Days', color: '#22C55E' },
      { name: 'Drive Belt', temp: '42.0°C', rpm: 1200, vibration: '0.14 mm/s', health: '90%', nextMaint: '20 Days', color: '#22C55E' },
    ],
    events: [
      { time: '10:40', text: 'Maintenance Scheduled for Motor Drive Shaft' },
      { time: '10:35', text: 'Engineer Assigned: Rajesh Kumar' },
      { time: '10:32', text: 'AI Prediction Generated: 82% Failure Probability' },
      { time: '10:25', text: 'Bearing Fatigue Warning Threshold Exceeded' },
      { time: '10:20', text: 'Temperature Increased above 80.0°C' },
    ],
    aiPrediction: {
      healthScore: 68,
      failureProbability: 82,
      remainingUsefulLifeHours: 34,
      modelName: 'XGBoost RUL Predictor v4.2',
      recommendation: 'Replace Drive Shaft Bearing within 12 hrs to prevent failure',
      rootCause: 'Main Drive Shaft Bearing Fatigue & Thermal Friction caused by lubricant contamination',
      secondaryAnomaly: 'Thermal Heat Dissipation Drop across Heald Frame',
      confidenceScore: 96.4,
      estimatedEstDowntimeHrs: 1.5,
      costSavingsUSD: 450,
    },
    maintenanceHistory: {
      lastMaintenanceDate: '15 Jul 2026',
      lastTask: 'Main Drive Shaft Bearing Replacement & Lube Calibration',
      engineer: 'Rajesh Kumar (Senior Shift Engineer)',
      nextMaintenanceDate: '15 Aug 2026',
    },
  };

  // Render Dynamic SVG Diagram according to Machine Type
  const renderDynamicMachineSVG = () => {
    switch (selectedMachineType) {
      case 'Rapier Loom':
        return (
          <svg width="340" height="190" viewBox="0 0 340 190" fill="none">
            <rect x="20" y="30" width="300" height="120" rx="10" fill="#F1F5F9" stroke="#0284C7" strokeWidth="2.5" />
            <path d="M40 90 L300 90" stroke="#0284C7" strokeWidth="4" strokeDasharray="6 6" />
            <circle cx="80" cy="90" r="28" fill="#E2E8F0" stroke="#0284C7" strokeWidth="3" />
            <text x="110" y="160" fill="#0F172A" fontSize="12" fontWeight="800">RAPIER FLEXIBLE TAPE SCHEMATIC</text>
          </svg>
        );
      case 'Water Jet Loom':
        return (
          <svg width="340" height="190" viewBox="0 0 340 190" fill="none">
            <rect x="20" y="30" width="300" height="120" rx="10" fill="#ECFEFF" stroke="#06B6D4" strokeWidth="2.5" />
            <circle cx="170" cy="90" r="35" fill="#CFFAFE" stroke="#06B6D4" strokeWidth="3" />
            <path d="M170 55 L170 125 M135 90 L205 90" stroke="#06B6D4" strokeWidth="3" />
            <text x="100" y="160" fill="#0F172A" fontSize="12" fontWeight="800">HIGH-PRESSURE WATER JET NOZZLE</text>
          </svg>
        );
      case 'Circular Knitting Machine':
        return (
          <svg width="340" height="190" viewBox="0 0 340 190" fill="none">
            <circle cx="170" cy="90" r="55" fill="#F3E8FF" stroke="#8B5CF6" strokeWidth="3" />
            <circle cx="170" cy="90" r="35" fill="#ffffff" stroke="#8B5CF6" strokeWidth="2" />
            <text x="105" y="165" fill="#0F172A" fontSize="12" fontWeight="800">CIRCULAR NEEDLE CYLINDER</text>
          </svg>
        );
      case 'Air Jet Loom':
      default:
        return (
          <svg width="340" height="190" viewBox="0 0 340 190" fill="none">
            <rect x="20" y="30" width="300" height="120" rx="10" fill="#EFF6FF" stroke="#2563EB" strokeWidth="2.5" />
            <rect x="50" y="60" width="80" height="60" rx="6" fill="#DBEAFE" stroke="#2563EB" strokeWidth="2" />
            <circle cx="230" cy="90" r="32" fill="#DBEAFE" stroke="#2563EB" strokeWidth="3" />
            <text x="105" y="160" fill="#0F172A" fontSize="12" fontWeight="800">AIR JET MAIN NOZZLE & COMPRESSOR</text>
          </svg>
        );
    }
  };

  // Graph 1: Thermal (°C) & Vibration (mm/s) Chart
  const thermalChartData = {
    labels: ['08:00', '08:30', '09:00', '09:30', '10:00', '10:30', '11:00'],
    datasets: [
      {
        label: 'Motor Temperature (°C)',
        data: [52, 54, 58, 64, 72, 79, 82],
        borderColor: '#EF4444',
        backgroundColor: 'rgba(239, 68, 68, 0.12)',
        tension: 0.4,
        fill: true,
      },
      {
        label: 'Shaft Vibration (mm/s)',
        data: [0.12, 0.14, 0.16, 0.19, 0.24, 0.31, 0.34],
        borderColor: '#8B5CF6',
        backgroundColor: 'transparent',
        tension: 0.4,
      },
    ],
  };

  // Graph 2: Loom Speed (RPM) & Main Air Nozzle Pressure (bar)
  const speedChartData = {
    labels: ['08:00', '08:30', '09:00', '09:30', '10:00', '10:30', '11:00'],
    datasets: [
      {
        label: 'Operating Speed (RPM)',
        data: [1020, 1040, 1050, 1060, 1050, 1080, 1075],
        borderColor: '#2563EB',
        backgroundColor: 'rgba(37, 99, 235, 0.1)',
        tension: 0.4,
        fill: true,
      },
      {
        label: 'Air Pressure (bar)',
        data: [4.8, 4.8, 4.7, 4.6, 4.5, 4.4, 4.2],
        borderColor: '#06B6D4',
        backgroundColor: 'transparent',
        tension: 0.4,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { position: 'top', labels: { font: { family: 'Plus Jakarta Sans', size: 11, weight: '700' } } },
    },
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

      {/* CASCADING FILTER CONTROL BAR */}
      <div
        className="glass-card"
        style={{
          padding: '1.25rem 1.5rem',
          background: '#ffffff',
          border: '1px solid #E2E8F0',
          borderRadius: '12px',
          display: 'flex',
          justify: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '1.25rem',
          boxShadow: '0 4px 15px rgba(0,0,0,0.02)',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '1.25rem', flexWrap: 'wrap', flex: 1 }}>
          <div className="form-group" style={{ marginBottom: 0, minWidth: '220px' }}>
            <label style={{ fontSize: '0.78rem', fontWeight: '800', color: '#475569' }}>1. Select Plant</label>
            <select
              className="form-control"
              value={selectedPlant}
              onChange={(e) => setSelectedPlant(e.target.value)}
              style={{ fontWeight: '700', borderColor: '#2563EB' }}
            >
              {plants.map((p) => (
                <option key={p} value={p}>{p}</option>
              ))}
            </select>
          </div>

          <div className="form-group" style={{ marginBottom: 0, minWidth: '200px' }}>
            <label style={{ fontSize: '0.78rem', fontWeight: '800', color: '#475569' }}>2. Machine Type</label>
            <select
              className="form-control"
              value={selectedMachineType}
              onChange={(e) => setSelectedMachineType(e.target.value)}
              style={{ fontWeight: '700', borderColor: '#2563EB' }}
            >
              {machineTypes.map((mt) => (
                <option key={mt} value={mt}>{mt}</option>
              ))}
            </select>
          </div>

          <div className="form-group" style={{ marginBottom: 0, minWidth: '180px' }}>
            <label style={{ fontSize: '0.78rem', fontWeight: '800', color: '#475569' }}>3. Loom Number</label>
            <select
              className="form-control"
              value={selectedMachineId}
              onChange={(e) => setSelectedMachineId(e.target.value)}
              style={{ fontWeight: '800', borderColor: '#2563EB', fontFamily: 'JetBrains Mono, monospace' }}
            >
              {availableMachines.map((m) => (
                <option key={m.id} value={m.id}>{m.id} - {m.name}</option>
              ))}
            </select>
          </div>
        </div>

        <button
          className="btn btn-primary"
          onClick={handleLoadDigitalTwin}
          style={{ background: '#2563EB', padding: '0.75rem 1.75rem', fontWeight: '800' }}
        >
          🚀 Load Digital Twin
        </button>
      </div>

      {/* MACHINE INFORMATION HEADER CARD */}
      <div
        className="glass-card"
        style={{
          padding: '1.25rem 1.5rem',
          background: '#ffffff',
          border: '1px solid #E2E8F0',
          borderRadius: '12px',
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
          gap: '1rem',
        }}
      >
        <div>
          <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '800' }}>MACHINE ID</div>
          <div style={{ fontSize: '1.2rem', fontWeight: '900', color: '#2563EB', fontFamily: 'JetBrains Mono' }}>{twin.machineId}</div>
        </div>
        <div>
          <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '800' }}>MANUFACTURER</div>
          <div style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A' }}>{twin.manufacturer}</div>
        </div>
        <div>
          <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '800' }}>MODEL</div>
          <div style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A' }}>{twin.model}</div>
        </div>
        <div>
          <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '800' }}>PLANT</div>
          <div style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A' }}>{selectedPlant.split(' ')[0]}</div>
        </div>
        <div>
          <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '800' }}>DEPARTMENT</div>
          <div style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A' }}>{twin.department}</div>
        </div>
        <div>
          <div style={{ fontSize: '0.74rem', color: '#64748B', fontWeight: '800' }}>STATUS</div>
          <span className="badge" style={{ background: '#DCFCE7', color: '#166534', fontWeight: '800' }}>🟢 {twin.status}</span>
        </div>
      </div>

      {/* DYNAMIC 3D MACHINE MODEL + AI PREDICTIVE DIAGNOSTICS CARD */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: '1.25rem' }}>

        {/* Dynamic 3D Model Card */}
        <div className="glass-card" style={{ padding: '1.5rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Cpu size={18} style={{ color: '#2563EB' }} /> Dynamic 3D Machine Model ({selectedMachineType})
            </h3>
            <span className="badge" style={{ background: '#EFF6FF', color: '#2563EB', fontWeight: '800' }}>8 Interactive Hotspots</span>
          </div>

          <div
            style={{
              height: '240px',
              background: '#F8FAFC',
              border: '1.5px dashed #CBD5E1',
              borderRadius: '10px',
              position: 'relative',
              display: 'flex',
              alignItems: 'center',
              justify: 'center',
              overflow: 'hidden',
            }}
          >
            {renderDynamicMachineSVG()}

            {/* Hotspot Indicators */}
            {twin.components.map((c, idx) => {
              const positions = [
                { top: '25%', left: '75%' }, // Motor
                { top: '35%', left: '25%' }, // Bearing
                { top: '50%', left: '50%' }, // Main Shaft
                { top: '70%', left: '20%' }, // Warp Beam
                { top: '45%', left: '85%' }, // Weft Sensor
                { top: '65%', left: '60%' }, // Air Nozzle
                { top: '80%', left: '70%' }, // Compressor
                { top: '30%', left: '40%' }, // Drive Belt
              ];
              const pos = positions[idx % positions.length];

              return (
                <div
                  key={c.name}
                  onClick={() => setInspectComponent(c)}
                  style={{
                    position: 'absolute',
                    top: pos.top,
                    left: pos.left,
                    transform: 'translate(-50%, -50%)',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.3rem',
                    background: '#ffffff',
                    padding: '0.35rem 0.6rem',
                    borderRadius: '20px',
                    border: `1.5px solid ${c.color}`,
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                  }}
                >
                  <span
                    style={{
                      width: '8px',
                      height: '8px',
                      borderRadius: '50%',
                      background: c.color,
                      boxShadow: `0 0 6px ${c.color}`,
                    }}
                  />
                  <span style={{ fontSize: '0.72rem', fontWeight: '800', color: '#0F172A' }}>{c.name}</span>
                </div>
              );
            })}
          </div>

          {/* Component Inspection Drawer */}
          {inspectComponent && (
            <div style={{ marginTop: '1rem', padding: '1rem', background: '#F5F3FF', border: '1px solid #8B5CF6', borderRadius: '8px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '0.9rem', fontWeight: '800', color: '#8B5CF6' }}>🔍 Component Hotspot: {inspectComponent.name}</span>
                <button onClick={() => setInspectComponent(null)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}><X size={16} /></button>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '0.75rem', marginTop: '0.75rem', fontSize: '0.8rem', color: '#0F172A', fontWeight: '700' }}>
                <div>Temp: <strong>{inspectComponent.temp}</strong></div>
                <div>RPM: <strong>{inspectComponent.rpm}</strong></div>
                <div>Health: <strong style={{ color: inspectComponent.color }}>{inspectComponent.health}</strong></div>
                <div>Next Maint: <strong>{inspectComponent.nextMaint}</strong></div>
              </div>
            </div>
          )}
        </div>

        {/* AI PREDICTION, REASON FOR PROBLEM & MAINTENANCE SUITE */}
        <div className="glass-card" style={{ padding: '1.5rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Sparkles size={18} style={{ color: '#8B5CF6' }} /> AI Predictive Diagnostics & RUL
            </h3>
            <span className="badge" style={{ background: '#8B5CF6', color: '#ffffff', fontWeight: '800' }}>{twin.aiPrediction.modelName}</span>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.75rem', marginBottom: '1rem' }}>
            <div style={{ padding: '0.75rem', background: '#F5F3FF', borderRadius: '8px', border: '1px solid #C4B5FD' }}>
              <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>HEALTH SCORE</div>
              <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#EF4444' }}>{twin.aiPrediction.healthScore}%</div>
            </div>
            <div style={{ padding: '0.75rem', background: '#F5F3FF', borderRadius: '8px', border: '1px solid #C4B5FD' }}>
              <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>FAILURE PROB.</div>
              <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#EF4444' }}>{twin.aiPrediction.failureProbability}%</div>
            </div>
            <div style={{ padding: '0.75rem', background: '#F5F3FF', borderRadius: '8px', border: '1px solid #C4B5FD' }}>
              <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>REMAINING RUL</div>
              <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#F59E0B' }}>{twin.aiPrediction.remainingUsefulLifeHours} Hrs</div>
            </div>
          </div>

          {/* PROMINENT REASON FOR PROBLEM & MAINTENANCE DETAILS BOX */}
          <div style={{ padding: '1.1rem', background: '#FEE2E2', border: '1.5px solid #EF4444', borderRadius: '10px', marginBottom: '1rem' }}>
            <div style={{ fontSize: '0.78rem', fontWeight: '800', color: '#991B1B', textTransform: 'uppercase', letterSpacing: '0.4px', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
              <AlertOctagon size={16} /> 🔍 REASON FOR MACHINE PROBLEM / ANOMALY DIAGNOSIS:
            </div>
            <div style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A', marginTop: '4px' }}>
              {twin.aiPrediction.rootCause}
            </div>
            <div style={{ fontSize: '0.8rem', color: '#64748B', marginTop: '2px', fontWeight: '700' }}>
              Secondary Anomaly: <span style={{ color: '#EF4444' }}>{twin.aiPrediction.secondaryAnomaly}</span>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '0.75rem', marginTop: '0.85rem', paddingTop: '0.75rem', borderTop: '1px solid #FCA5A5' }}>
              <div>
                <div style={{ fontSize: '0.72rem', color: '#991B1B', fontWeight: '800', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                  <UserCheck size={13} /> LAST MAINTENANCE COMPLETED:
                </div>
                <div style={{ fontSize: '0.84rem', fontWeight: '800', color: '#0F172A', marginTop: '2px' }}>
                  {twin.maintenanceHistory.lastMaintenanceDate} — {twin.maintenanceHistory.lastTask}
                </div>
                <div style={{ fontSize: '0.75rem', color: '#64748B', fontWeight: '700' }}>Engineer: {twin.maintenanceHistory.engineer}</div>
              </div>

              <div>
                <div style={{ fontSize: '0.72rem', color: '#991B1B', fontWeight: '800', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                  <Calendar size={13} /> NEXT SCHEDULED MAINTENANCE:
                </div>
                <div style={{ fontSize: '0.84rem', fontWeight: '800', color: '#2563EB', marginTop: '2px' }}>
                  {twin.maintenanceHistory.nextMaintenanceDate}
                </div>
                <div style={{ fontSize: '0.75rem', color: '#EF4444', fontWeight: '800' }}>AI Action: {twin.aiPrediction.recommendation}</div>
              </div>
            </div>

            <div style={{ marginTop: '0.85rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span style={{ fontSize: '0.78rem', color: '#166534', fontWeight: '800', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                <DollarSign size={14} /> Estimated Savings: +${twin.aiPrediction.costSavingsUSD} if serviced within {twin.aiPrediction.estimatedEstDowntimeHrs}h
              </span>
              <button
                className="btn btn-primary btn-sm"
                onClick={() => navigate('/maintenance')}
                style={{ background: '#EF4444', borderColor: '#EF4444', fontSize: '0.76rem', fontWeight: '800' }}
              >
                <Wrench size={14} /> Dispatch Repair Order
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* SEPARATE DUAL MULTI-SIGNAL SENSOR CHARTS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: '1.25rem' }}>

        {/* Graph 1: Thermal & Vibration Trends */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <h4 style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.75rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Thermometer size={16} style={{ color: '#EF4444' }} /> Motor Temperature (°C) & Shaft Vibration (mm/s)
          </h4>
          <div style={{ height: '180px', width: '100%' }}>
            <Line data={thermalChartData} options={chartOptions} />
          </div>
        </div>

        {/* Graph 2: Speed & Air Pressure Trends */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <h4 style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.75rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Gauge size={16} style={{ color: '#2563EB' }} /> Operating Speed (RPM) & Main Air Nozzle Pressure (bar)
          </h4>
          <div style={{ height: '180px', width: '100%' }}>
            <Line data={speedChartData} options={chartOptions} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default DigitalTwinPage;
